ds-button.css:
.ds-button {
  align-items: center;
  background: #4a46c4;
  border: 1px solid transparent;
  border-radius: 0.625rem;
  color: #ffffff;
  display: inline-flex;
  font-family: 'Source Sans 3', ui-sans-serif, system-ui, sans-serif;
  font-weight: 600;
  gap: 0.5rem;
  min-height: 2.75rem;
  padding-inline: 1.25rem;
  text-decoration: none;
  transition: background 120ms cubic-bezier(0.16, 1, 0.3, 1);
}
.ds-button:hover { background: #3c39a3; }
.ds-button:active { transform: translateY(1px); }
.ds-button-secondary {
  background: #ffffff;
  border-color: #cbd4e3;
  color: #1a2233;
}
.ds-button-secondary:hover { background: #eff3f9; border-color: #c2c2ef; }

ds-nav-item.css:
.ds-nav { display: flex; flex-direction: column; gap: 0.125rem; width: 16rem; }
.ds-nav-heading {
  color: #7b8aa5;
  font-family: 'Familjen Grotesk', ui-sans-serif, system-ui, sans-serif;
  font-size: 0.6875rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  margin: 0 0 0.5rem;
  text-transform: uppercase;
}
.ds-nav-item {
  border-radius: 0.375rem;
  color: #5a6880;
  font-family: 'Source Sans 3', ui-sans-serif, system-ui, sans-serif;
  font-size: 0.9375rem;
  padding: 0.5rem 0.75rem;
  text-decoration: none;
}
.ds-nav-item:hover { background: #eff3f9; color: #1a2233; }
.ds-nav-item[aria-current='page'] {
  background: #eff0fb;
  box-shadow: inset 2px 0 0 #4a46c4;
  color: #4a46c4;
  font-weight: 600;
}

ds-search-result.css:
.ds-search-results { list-style: none; margin: 0; padding: 0.5rem; }
.ds-search-result {
  border-radius: 0.625rem;
  color: #1a2233;
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  padding: 0.75rem;
  text-decoration: none;
}
.ds-search-result[aria-selected='true'] { background: #eff0fb; }
.ds-search-result-title {
  font-family: 'Familjen Grotesk', ui-sans-serif, system-ui, sans-serif;
  font-weight: 700;
}
.ds-search-result-section {
  background: #ffffff;
  border: 1px solid #e3e9f2;
  border-radius: 999px;
  color: #5a6880;
  font-size: 0.6875rem;
  letter-spacing: 0.06em;
  padding: 0.1rem 0.5rem;
  text-transform: uppercase;
}
.ds-search-result-excerpt {
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  color: #5a6880;
  display: -webkit-box;
  font-family: 'Source Sans 3', ui-sans-serif, system-ui, sans-serif;
  font-size: 0.9375rem;
  overflow: hidden;
}

ds-aside.css:
.ds-aside {
  background: #eff0fb;
  border: 1px solid #c2c2ef;
  border-radius: 0.625rem;
  color: #1a2233;
  font-family: 'Source Sans 3', ui-sans-serif, system-ui, sans-serif;
  padding: 1rem 1.25rem;
}
.ds-aside p { margin: 0.25rem 0; }
.ds-aside-title {
  color: #3c39a3;
  font-family: 'Familjen Grotesk', ui-sans-serif, system-ui, sans-serif;
  font-size: 0.6875rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}
.ds-aside-warning { background: #fdf9e9; border-color: #d9b02f; }
.ds-aside-warning .ds-aside-title { color: #6f550a; }

ds-table.css:
.ds-table {
  border-collapse: collapse;
  font-family: 'Source Sans 3', ui-sans-serif, system-ui, sans-serif;
  width: 100%;
}
.ds-table th {
  background: #eff3f9;
  border-bottom: 1px solid #cbd4e3;
  color: #5a6880;
  font-family: 'Familjen Grotesk', ui-sans-serif, system-ui, sans-serif;
  font-size: 0.6875rem;
  letter-spacing: 0.06em;
  padding: 0.75rem 1rem;
  text-align: left;
  text-transform: uppercase;
}
.ds-table td {
  border-bottom: 1px solid #e3e9f2;
  color: #1a2233;
  padding: 0.75rem 1rem;
}
.ds-table tbody tr:hover { background: #eff0fb; }

ds-doc-heading.css:
.ds-doc-heading {
  border-top: 1px solid #e3e9f2;
  color: #1a2233;
  font-family: 'Familjen Grotesk', ui-sans-serif, system-ui, sans-serif;
  font-size: clamp(1.5rem, 1.34rem + 0.8vw, 1.9rem);
  margin: 4rem 0 1rem;
  padding-top: 2rem;
}
.ds-heading-anchor {
  color: #7b8aa5;
  margin-left: 0.5rem;
  opacity: 0;
  text-decoration: none;
  transition: opacity 120ms cubic-bezier(0.16, 1, 0.3, 1);
}
.ds-heading-anchor::after { content: '#'; }
.ds-doc-heading:hover .ds-heading-anchor,
.ds-heading-anchor:focus-visible { opacity: 1; }
@media (hover: none) { .ds-heading-anchor { opacity: 1; } }
